const riseWindowMs = 10 * 60 * 1000;
const riseThreshold = 5;
const absoluteThreshold = 63;
const minimumBoostMs = 30 * 60 * 1000;
const maximumBoostMs = 60 * 60 * 1000;
const dryMargin = 3;
const maximumDryTarget = 65;
const cooldownMs = 10 * 60 * 1000;

const now = Date.now();
const humidity = Number(msg.payload);

if (!Number.isFinite(humidity) || humidity < 0 || humidity > 100) {
    node.status({ fill: 'red', shape: 'ring', text: 'Ungültiger Feuchtewert' });
    return null;
}

let samples = context.get('samples') || [];
samples.push({ time: now, value: humidity });
samples = samples.filter(sample => now - sample.time <= riseWindowMs);
context.set('samples', samples);

let boostActive = context.get('boostActive') === true;
let boostStartedAt = Number(context.get('boostStartedAt')) || 0;
let baseline = Number(context.get('baseline'));
let lastStoppedAt = Number(context.get('lastStoppedAt')) || 0;

const recentMinimum = Math.min(...samples.map(sample => sample.value));
const rise = humidity - recentMinimum;

if (!boostActive) {
    const cooldownActive = lastStoppedAt > 0 && now - lastStoppedAt < cooldownMs;
    const shouldStart = !cooldownActive && (rise >= riseThreshold || humidity >= absoluteThreshold);

    if (!shouldStart) {
        const text = cooldownActive
            ? `Pause · ${humidity.toFixed(1)} %`
            : `${humidity.toFixed(1)} % · Anstieg ${rise.toFixed(1)} %`;
        node.status({ fill: 'green', shape: 'dot', text });
        return null;
    }

    baseline = recentMinimum;
    boostActive = true;
    boostStartedAt = now;

    context.set('baseline', baseline);
    context.set('boostActive', true);
    context.set('boostStartedAt', boostStartedAt);

    node.status({
        fill: 'yellow',
        shape: 'dot',
        text: `Boost gestartet · ${humidity.toFixed(1)} %`
    });

    return [
        {
            payload: humidity,
            baseline,
            reason: rise >= riseThreshold ? 'Feuchteanstieg' : 'Absolutgrenze'
        },
        null
    ];
}

const elapsed = now - boostStartedAt;
const dryTarget = Math.min(baseline + dryMargin, maximumDryTarget);
const dryEnough = humidity <= dryTarget;
const minimumReached = elapsed >= minimumBoostMs;
const maximumReached = elapsed >= maximumBoostMs;

node.status({
    fill: 'yellow',
    shape: 'dot',
    text: `Boost ${Math.floor(elapsed / 60000)} min · ${humidity.toFixed(1)} %`
});

if (!maximumReached && !(minimumReached && dryEnough)) {
    return null;
}

context.set('boostActive', false);
context.set('boostStartedAt', 0);
context.set('lastStoppedAt', now);
context.set('samples', [{ time: now, value: humidity }]);

node.status({
    fill: 'blue',
    shape: 'ring',
    text: maximumReached ? 'Boost-Zeit abgelaufen' : 'Bad wieder trocken'
});

return [
    null,
    {
        payload: humidity,
        baseline,
        reason: maximumReached ? 'Maximallaufzeit' : 'Feuchte abgebaut'
    }
];
